const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Get Zimbabwe boundary from FAO GAUL
  const zimbabwe = ee.FeatureCollection('FAO/GAUL/2015/level0')
    .filter(ee.Filter.eq('ADM0_NAME', 'Zimbabwe'));
  // Define date ranges for February 2024 and February 2023
  const feb2024Start = '2024-02-01';
  const feb2024End = '2024-02-29'; // 2024 is a leap year
  const feb2023Start = '2023-02-01';
  const feb2023End = '2023-02-28';

  // Helper function to process a month
  async function processMonth(startDate, endDate, label) {
    // Filter CHIRPS daily collection
    let chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
      .filterDate(startDate, endDate)
      .select('precipitation');

    // Check collection size
    const size = chirps.size().getInfo();
    console.log(`${label} Images: ${size}`);
    if (size === 0) {
      // Try fallback: ERA5-Land monthly aggregated (if CHIRPS fails)
      // For rainfall, we can use ERA5-Land's total precipitation
      // But note: ERA5-Land is reanalysis, not exactly the same.
      // We'll try to recover with ERA5-Land monthly.
      console.log(`No CHIRPS data for ${label}, trying ERA5-Land.`);
      // ERA5-Land monthly: "ECMWF/ERA5_LAND/MONTHLY"
      // Band: 'total_precipitation_sum' (in meters, convert to mm by *1000)
      const era5 = ee.ImageCollection('ECMWF/ERA5_LAND/MONTHLY')
        .filterDate(startDate, endDate)
        .select('total_precipitation_sum');
      const era5Size = era5.size().getInfo();
      console.log(`ERA5 ${label} Images: ${era5Size}`);
      if (era5Size === 0) {
        return { mean: null, count: 0, label: label, error: 'C1' };
      }
      // Sum the monthly images (usually one image per month)
      const monthlySum = era5.sum().multiply(1000); // Convert m to mm
      // Rename band for consistency
      const rainfall = monthlySum.rename('precipitation');
      // Compute statistics
      const stats = rainfall.reduceRegion({
        reducer: ee.Reducer.mean().combine({
          reducer2: ee.Reducer.count(),
          sharedInputs: true
        }),
        geometry: zimbabwe,
        scale: 10000, // ERA5-Land resolution is ~11 km
        maxPixels: 1e9
      });
      const mean = stats.get('precipitation_mean');
      const count = stats.get('precipitation_count');
      return { mean: mean, count: count, label: label, error: null };
    }

    // Sum daily precipitation to get monthly total
    const monthlySum = chirps.sum();

    // Compute mean rainfall and pixel count over Zimbabwe
    const stats = monthlySum.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: zimbabwe,
      scale: 5000, // CHIRPS resolution is ~5.5 km
      maxPixels: 1e9
    });

    const mean = stats.get('precipitation_mean');
    const count = stats.get('precipitation_count');
    return { mean: mean, count: count, label: label, error: null };
  }

  // Process both months
  const month2023 = await processMonth(feb2023Start, feb2023End, 'Feb2023');
  const month2024 = await processMonth(feb2024Start, feb2024End, 'Feb2024');

  // Check for errors (C1: empty collection)
  if (month2023.error === 'C1' || month2024.error === 'C1') {
    console.log('C1: Empty collection for one or both months.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get the values
  const mean2023 = month2023.mean.getInfo();
  const count2023 = month2023.count.getInfo();
  const mean2024 = month2024.mean.getInfo();
  const count2024 = month2024.count.getInfo();

  // Check for valid pixels (C2)
  if (count2023 === 0 || count2024 === 0) {
    console.log(`Feb2023 valid pixels: ${count2023}, Feb2024 valid pixels: ${count2024}`);
    console.log('C2: No valid pixels in one or both months.');
    console.log('<answer>C2</answer>');
    return;
  }

  // Validate results (C3)
  if (mean2023 === null || mean2024 === null || 
      isNaN(mean2023) || isNaN(mean2024) ||
      mean2023 < 0 || mean2024 < 0 || // Rainfall shouldn't be negative
      mean2023 > 10000 || mean2024 > 10000) { // Unrealistically high (in mm)
    console.log(`Feb2023 mean: ${mean2023}, Feb2024 mean: ${mean2024}`);
    console.log('C3: Invalid calculation result.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Print evidence
  console.log(`Feb2023 mean rainfall (mm): ${mean2023.toFixed(2)}`);
  console.log(`Feb2024 mean rainfall (mm): ${mean2024.toFixed(2)}`);
  console.log(`Feb2023 pixel count: ${count2023}`);
  console.log(`Feb2024 pixel count: ${count2024}`);

  // Determine answer
  if (mean2024 < mean2023) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
